import { html, unsafeCSS } from "lit";
import { property } from "lit/decorators.js";
import { NysElement } from "@nysds/internals";
// This element is rendered inside this component's shadow DOM (prefix/suffix
// icons), so it must be registered whenever nys-badge is used. Importing it
// here (intentional side effect) guarantees it always renders.
import "@nysds/nys-icon";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-badge.scss?inline";

/**
 * A compact label for status, counts, or categorization. Supports semantic intents with auto-selected icons.
 *
 * Use badges to highlight metadata like status ("Approved"), counts ("3 new"), or categories.
 * Set `intent` to apply semantic meaning. Add `prefixIcon` or `suffixIcon` as boolean for default icons,
 * or pass icon name strings for custom icons.
 *
 * @summary Compact label for status, counts, or categorization with semantic styling.
 * @element nys-badge
 *
 * @usage
 * - Indicate the status of an item, such as "new", "updated", or "beta".
 * - Provide additional context or information about an item without cluttering the interface.
 * - Keep badge labels short -- one or two words like "New", "Beta", or "Updated".
 * - Use the `intent` property to match the badge's visual style to its meaning (e.g., `success` for positive statuses, `warning` for caution).
 * - Place badges near the element they describe so the relationship is clear.
 * - Use the `prefixIcon` or `suffixIcon` attributes to reinforce meaning when the label alone may be ambiguous.
 * - Apply the `strong` variant when the badge appears on a raised surface or needs extra emphasis.
 * - Don't use badges when the information is too complex to be conveyed in a small badge.
 * - Don't use badges when they would not add significant value to the user experience.
 * - Don't use badges as interactive elements -- they are not buttons or links.
 * - Don't pack long sentences or multiple values into a single badge label.
 * - Don't mix badge sizes within the same group; pick either `md` or `sm` and stay consistent.
 * - Don't rely on color alone to convey meaning; always include a text label.
 * - Don't stack multiple badges on a single element unless each communicates a distinct, necessary status.
 *
 * @example Basic
 * ```html
 * <nys-badge label="Basic badge"></nys-badge>
 * ```
 *
 * @example Info Intent
 * ```html
 * <nys-badge label="Info" intent="info" prefixIcon></nys-badge>
 * ```
 *
 * @example Success Intent
 * ```html
 * <nys-badge label="Success" intent="success" prefixIcon></nys-badge>
 * ```
 *
 * @example Warning Intent
 * ```html
 * <nys-badge label="Warning" intent="warning" prefixIcon></nys-badge>
 * ```
 *
 * @example Danger Intent
 * ```html
 * <nys-badge label="Danger" intent="danger" prefixIcon></nys-badge>
 * ```
 *
 * @example Emergency Intent
 * ```html
 * <nys-badge label="Emergency" intent="emergency" prefixIcon></nys-badge>
 * ```
 *
 * @example Strong Base
 * ```html
 * <nys-badge strong label="Base" prefixIcon></nys-badge>
 * ```
 *
 * @example Strong Info
 * ```html
 * <nys-badge strong label="Info" intent="info" prefixIcon></nys-badge>
 * ```
 *
 * @example Strong Success
 * ```html
 * <nys-badge strong label="Success" intent="success" prefixIcon></nys-badge>
 * ```
 *
 * @example Strong Warning
 * ```html
 * <nys-badge strong label="Warning" intent="warning" prefixIcon></nys-badge>
 * ```
 *
 * @example Strong Danger
 * ```html
 * <nys-badge strong label="Danger" intent="danger" prefixIcon></nys-badge>
 * ```
 *
 * @example Custom Prefix Icon
 * ```html
 * <nys-badge label="Custom prefixIcon" prefixIcon="check"></nys-badge>
 * ```
 *
 * @example Custom Suffix Icon
 * ```html
 * <nys-badge label="Custom suffixIcon" suffixIcon="check"></nys-badge>
 * ```
 *
 * @example Size Small
 * ```html
 * <nys-badge label="Small" size="sm"></nys-badge>
 * ```
 *
 * @example Screen reader text
 * ```html
 * <nys-badge intent="warning" label="Caution" prefixIcon srText="concern"></nys-badge>
 * ```
 */

export class NysBadge extends NysElement {
  static styles = unsafeCSS(styles);

  /** Unique identifier. */
  @property({
    type: String,
    reflect: true,
    converter: {
      toAttribute: (value: string) => (value ? value : undefined),
    },
  })
  id = "";

  /** Name attribute for form association. */
  @property({
    type: String,
    reflect: true,
    converter: {
      toAttribute: (value: string) => (value ? value : undefined),
    },
  })
  name = "";

  /**
   * Badge size: `sm` (smaller text) or `md` (default).
   * @default "md"
   */
  @property({ type: String, reflect: true }) size: "sm" | "md" = "md";

  /**
   * Semantic intent affecting color: `base`, `info`, `success`, `warning` `danger`, `emergency`. `error` has been deprecated and support will be removed in a future release. Use `danger` instead
   * @default "info"
   */
  @property({ type: String, reflect: true }) intent:
    | "base"
    | "info"
    | "success"
    | "warning"
    | "danger"
    | "error"
    | "emergency" = "base";

  /** Secondary label displayed before the main label. */
  @property({ type: String }) prefixLabel = "";

  /** Primary label text displayed in the badge. */
  @property({ type: String }) label = "";

  /** Screen reader text appended after the label for additional context. */
  @property({ type: String }) srText = "";

  /** Strong visual intent with bolder text and background. */
  @property({ type: Boolean, reflect: true }) strong = false;

  /** Icon shown before the label. */
  @property({ type: String, attribute: "prefixicon" })
  prefixIcon: string | boolean | null = null;

  /** Icon shown after the label. */
  @property({ type: String, attribute: "suffixicon" })
  suffixIcon: string | boolean | null = null;

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   */

  connectedCallback() {
    // super.connectedCallback() (NysElement) auto-assigns an id when
    // one is not provided, preserving the "nys-badge-<ts>-<n>" shape. A badge is
    // static, non-interactive label content, so no host role is reflected
    // (defaultRole stays null).
    super.connectedCallback();
  }

  /**
   * Functions
   * --------------------------------------------------------------------------
   */

  // Map of default icons by intent
  private static readonly DEFAULT_ICONS: Record<string, string> = {
    base: "info",
    info: "info",
    success: "check_circle",
    warning: "warning",
    danger: "error",
    error: "error",
    emergency: "emergency_home",
  };

  // WCAG 1.4.1 (Use of Color): intent is otherwise conveyed only by color and a
  // decorative (aria-hidden) icon. Provide a screen-reader-only text alternative
  // so the semantic meaning is not color-only. Skipped for "base" (no
  // semantic meaning) and when the author supplies their own srText override.
  private static readonly INTENT_SR_TEXT: Record<string, string> = {
    info: "Info",
    success: "Success",
    warning: "Warning",
    danger: "Danger",
    error: "Danger",
    emergency: "Emergency",
  };

  /**
   * Resolves the screen-reader-only text describing the badge's semantic intent.
   * Returns null when no intent description should be announced.
   */
  private resolveIntentSrText(): string | null {
    if (this.srText) return null; // author-provided text takes precedence
    return NysBadge.INTENT_SR_TEXT[this.intent] ?? null;
  }

  /**
   * Resolves which icon should be rendered.
   * @param icon The icon property value (string or boolean)
   * @returns Icon name or null if no icon should be rendered
   */
  private resolveIcon(icon: string | boolean | null): string | null {
    if (icon === true || icon === "") {
      return NysBadge.DEFAULT_ICONS[this.intent] ?? "info";
    }
    if (typeof icon === "string" && icon.trim() !== "" && icon !== "false") {
      return icon;
    }
    return null;
  }

  render() {
    const prefixIconName = this.resolveIcon(this.prefixIcon);
    const suffixIconName = this.resolveIcon(this.suffixIcon);
    const intentSrText = this.resolveIntentSrText();

    return html`
      <mark class="nys-badge">
        ${prefixIconName
          ? html`<nys-icon size="16" name=${prefixIconName}></nys-icon>`
          : ""}
        ${this.prefixLabel
          ? html`<div class="nys-badge__prefix">${this.prefixLabel}</div>`
          : ""}
        <div class="nys-badge__label">
          ${intentSrText
            ? html`<span class="nys-badge__sr-only"
                >${intentSrText + ": "}</span
              >`
            : ""}
          ${this.label}
          ${this.srText
            ? html`<span class="nys-badge__sr-only"
                >${": " + this.srText}</span
              >`
            : ""}
        </div>

        ${suffixIconName
          ? html`<nys-icon size="16" name=${suffixIconName}></nys-icon>`
          : ""}
      </mark>
    `;
  }
}

if (!customElements.get("nys-badge")) {
  customElements.define("nys-badge", NysBadge);
}
